package test;
import org.bukkit.*;import org.bukkit.entity.Player;import org.bukkit.event.*;import org.bukkit.event.entity.EntityDamageByEntityEvent;import org.bukkit.event.player.PlayerJoinEvent;import org.bukkit.plugin.java.JavaPlugin;import java.lang.reflect.*;import java.util.*;import net.minecraft.server.level.ServerPlayer;
public class ModeProbe extends JavaPlugin implements Listener {
 String mode="none";public void onEnable(){getServer().getPluginManager().registerEvents(this,this);}
 @EventHandler public void join(PlayerJoinEvent e){Player p=e.getPlayer();if(!p.getName().equals("TestOwner"))return;getServer().getScheduler().runTaskLater(this,()->{try{World w=p.getWorld();for(int x=-8;x<=8;x++)for(int z=-8;z<=8;z++){w.getBlockAt(x,99,z).setType(Material.STONE);for(int y=100;y<104;y++)w.getBlockAt(x,y,z).setType(Material.AIR);}p.teleport(new Location(w,.5,100,.5,0,0));JavaPlugin bp=(JavaPlugin)getServer().getPluginManager().getPlugin("ElytrixBotsTrain");Method spawn=bp.getClass().getDeclaredMethod("spawn",Player.class);spawn.setAccessible(true);spawn.invoke(bp,p);Field f=bp.getClass().getDeclaredField("bots");f.setAccessible(true);ServerPlayer bot=(ServerPlayer)((Map<?,?>)f.get(bp)).get(p.getUniqueId());Player fake=bot.getBukkitEntity();for(int i=0;i<4;i++){String m=new String[]{"crit","combo","pro","noob"}[i];getServer().getScheduler().runTaskLater(this,()->{mode=m;p.setHealth(p.getMaxHealth());p.teleport(new Location(w,.5,100,.5,0,0));fake.teleport(new Location(w,.5,100,2.5,180,0));bp.getConfig().set("players."+p.getUniqueId()+".mode",m);getLogger().info("MODE "+m);},1+100L*i);}}catch(Throwable t){getLogger().log(java.util.logging.Level.SEVERE,"FAIL",t);}},30L);}
 @EventHandler(priority=EventPriority.MONITOR,ignoreCancelled=true) public void damage(EntityDamageByEntityEvent e){if(e.getDamager().getName().startsWith("ElytrixBots_") && e.getEntity() instanceof Player p){ServerPlayer bot=((org.bukkit.craftbukkit.entity.CraftPlayer)e.getDamager()).getHandle();getLogger().info("HIT mode="+mode+" distance="+bot.getBukkitEntity().getLocation().distance(p.getLocation())+" damage="+e.getFinalDamage()+" fall="+bot.fallDistance+" sprint="+bot.isSprinting());}}
}
